import json,sys;d=json.load(sys.stdin);f=d.get('features',{})
print('$m', len(f), {k:(str(v.get('properties',{}).get('value'))[:160]) for k,v in f.items() if k in ('processed_sim_time','top_text','fc_text','queue_text','status_text','idSimulationRun','hit_rate','auto_call')})"; done

